import { Injectable } from '@angular/core';
import { ApiServiceService, StandarResponse } from '../services/api/api-service.service';
import { Usuario } from '../models/usuario.model';
import { catchError, firstValueFrom, lastValueFrom, throwError } from 'rxjs';
import { LocalStorageService } from '../services/localStorage/local-storage.service';
import { UsuarioLogin } from './auth.model';
import { VanillaDialogService } from '../services/vanilla-dialog/vanilla-dialog.service';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { environment } from '../../environments/environment';

const api= environment.api_url

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  constructor( private http: HttpClient, private storage:LocalStorageService, private dialog: VanillaDialogService ) { }

  public async login(credentials: Partial<Usuario>): Promise<UsuarioLogin | null> {
    try {
      const res = await lastValueFrom(
        this.http.post<StandarResponse<UsuarioLogin>>(`${api}/api/auth/login`, { data: credentials }).pipe(
          catchError((error: HttpErrorResponse) => {
            this.dialog.show({
              title: 'Login incorrecto',
              body: error.error?.message || 'Error desconocido',
              tipo: 'danger'
            });
            return throwError(() => error);
          })
        )
      );
  
      if (res.data && res.status) {
        this.storage.setUser(res.data);
        return res.data;
      }
  
      this.dialog.show({
        title: 'Error',
        body: 'Correo o contraseña incorrectos',
        tipo: 'danger'
      });
      return null;
    } catch (error) {
      return null;
    }
  }
}
